	private static List<List<Long>> drain(JaninoKernel kernel) {
		var rows = new ArrayList<List<Long>>();
		var page = new long[4];
		int count;
		while ((count = kernel.fill(page, 2)) != 0) {
			for (int row = 0; row < count; row++) {
				rows.add(List.of(page[2 * row], page[2 * row + 1]));
			}
		}
		return rows;
	}

